async function step(fn: () => Promise<void>): Promise<void> {
  await act(async () => {
    await fn();
  });
}

async function setup(name = 'alice', options: { offsetMinutes?: number; online?: boolean } = {}): Promise<{ world: World; c: Client }> {
  const world = makeWorld();
  const c = makeClient(world, { offsetMinutes: options.offsetMinutes ?? 0 });
  c.engine.login(name);
  render(<ChatScreen engine={c.engine} scheduler={world.time} />);
  if (options.online !== false) {
    await step(() => world.time.runUntil(() => snap(c).connection === 'online'));
  }
  return { world, c };
}

function openConversation(name: string) {
  fireEvent.change(screen.getByTestId('new-conversation-input'), { target: { value: name } });
  fireEvent.click(screen.getByTestId('new-conversation-submit'));
}

function compose(text: string) {
  fireEvent.change(screen.getByTestId('composer-input'), { target: { value: text } });
  fireEvent.click(screen.getByTestId('composer-send'));
}

function messageIds(): string[] {
  return Array.from(screen.getByTestId('message-list').querySelectorAll('[data-testid^="message-"]'))
    .map((el) => el.getAttribute('data-testid') ?? '')
    .filter((id) => !id.startsWith('message-time-'));
}

function conversationItems(): string[] {
  return Array.from(screen.getByTestId('conversation-list').querySelectorAll('[data-testid^="conversation-item-"]')).map(
    (el) => el.textContent ?? '',
  );
}

